import sys
from pathlib import Path
from unittest.mock import Mock, patch

import pytest

sys.path.insert(0, str(Path(__file__).resolve().parent.parent / "src"))

from retry import RetryExhaustedError, get_with_retry


def _response(status_code):
    response = Mock()
    response.status_code = status_code
    return response


@patch("retry.time.sleep", return_value=None)
@patch("retry.requests.get")
def test_returns_immediately_on_success(mock_get, mock_sleep):
    mock_get.return_value = _response(200)

    result = get_with_retry("http://example.com")

    assert result.status_code == 200
    mock_get.assert_called_once()
    mock_sleep.assert_not_called()


@patch("retry.time.sleep", return_value=None)
@patch("retry.requests.get")
def test_returns_immediately_on_non_503_error(mock_get, mock_sleep):
    mock_get.return_value = _response(500)

    result = get_with_retry("http://example.com")

    assert result.status_code == 500
    mock_get.assert_called_once()
    mock_sleep.assert_not_called()


@patch("retry.time.sleep", return_value=None)
@patch("retry.requests.get")
def test_retries_then_succeeds(mock_get, mock_sleep):
    mock_get.side_effect = [_response(503), _response(503), _response(200)]

    result = get_with_retry("http://example.com", max_attempts=5)

    assert result.status_code == 200
    assert mock_get.call_count == 3
    assert mock_sleep.call_count == 2


@patch("retry.time.sleep", return_value=None)
@patch("retry.requests.get")
def test_gives_up_after_max_attempts_on_persistent_503(mock_get, mock_sleep):
    mock_get.return_value = _response(503)

    with pytest.raises(RetryExhaustedError):
        get_with_retry("http://example.com", max_attempts=5)

    assert mock_get.call_count == 5
    assert mock_sleep.call_count == 4

