    mock_get.return_value = _response(503)

    with pytest.raises(requests.exceptions.HTTPError):
        get_with_retry("http://example.com", max_retries=3)

    assert mock_get.call_count == 4  # initial attempt + 3 retries


@patch("retry.time.sleep", return_value=None)
@patch("retry.requests.get")
def test_succeeds_after_transient_503s(mock_get, mock_sleep):
    mock_get.side_effect = [_response(503), _response(503), _response(200)]

    result = get_with_retry("http://example.com", max_retries=5)

    assert result.status_code == 200
    assert mock_get.call_count == 3


@patch("retry.time.sleep", return_value=None)
@patch("retry.requests.get")
def test_non_503_error_returns_immediately_without_retrying(mock_get, mock_sleep):
    mock_get.return_value = _response(404)

    result = get_with_retry("http://example.com")

    assert result.status_code == 404
    mock_sleep.assert_not_called()
